'use client'
/**
 * AvailabilitySignal — honest "call ahead" notice.
 *
 * This used to render a status like "Limited availability · ~46 min wait ·
 * 9 reported today" that was generated by a random-number generator seeded
 * on the clinic ID and the current hour (lib/availability.ts, now deleted).
 * Nothing was ever reported by anyone, and the "Notify me" button only wrote
 * to localStorage -- no notification could ever be sent. Showing invented
 * wait times to people deciding where to get care is worse than showing
 * nothing, so until we have real crowd reports this just tells people the
 * truth: we don't track live hours or wait times, call first.
 */
import { Call } from 'iconsax-react'

interface Props {
  clinicId: string
  clinicName: string
  /** If true, renders the full block (detail page). Compact = card badge. */
  variant?: 'compact' | 'full'
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
export default function AvailabilitySignal({ clinicId, clinicName, variant = 'compact' }: Props) {
  if (variant === 'compact') {
    return (
      <span style={{ fontSize: 11, color: 'rgba(255,255,255,0.4)', fontFamily: 'var(--font-inter)' }}>
        Call ahead to confirm hours
      </span>
    )
  }

  return (
    <div style={{
      background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.09)',
      borderRadius: 14, padding: '16px 20px',
      display: 'flex', alignItems: 'center', gap: 12,
    }}>
      <div style={{
        width: 32, height: 32, borderRadius: 8, flexShrink: 0,
        background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
      }}>
        <Call size={15} color="rgba(255,255,255,0.6)" variant="Linear" />
      </div>
      <div>
        <div style={{ fontSize: 13, fontWeight: 700, color: 'var(--text)', fontFamily: 'var(--font-inter)', marginBottom: 2 }}>
          Call before you go
        </div>
        <div style={{ fontSize: 12, color: 'rgba(255,255,255,0.5)', fontFamily: 'var(--font-inter)' }}>
          AXVO doesn&apos;t track live hours or wait times. Call {clinicName} to confirm they&apos;re open and taking walk-ins.
        </div>
      </div>
    </div>
  )
}
